           ("(lambda d: (d.pop('e2'), d.pop('e2', None), d.popitem(), d))({'a1': 'wR', 'e2': 'wP', 'h8': 'bR'})", "('wP', None, ('h8', 'bR'), {'a1': 'wR'})"),
           ("(lambda b: (b.__setitem__('e4', b.pop('e2')), b)[1])({'e2': 'wP', 'e1': 'wK'})", "{'e1': 'wK', 'e4': 'wP'}"),
           ("(lambda a, b: (a | b, a))({'x': 1, 'y': 2}, {'y': 20})", "({'x': 1, 'y': 20}, {'x': 1, 'y': 2})"),
           ("(lambda a, b: ({**a, **b} == a | b))({'x': 1, 'y': 2}, {'y': 20})", "True"),
           ("(lambda a: (a.__ior__([('b', 2)]) is a, a))({'a': 1})", "(True, {'a': 1, 'b': 2})"),
           ("(lambda d: (d.update({'x': 1}, y=2), d)[1])({})", "{'x': 1, 'y': 2}"), ("(lambda d: d.update({'x': 1}))({})", "None"),
           ("(lambda a, b: (a | b, {'k': {'a': 1}} | {'k': {'b': 2}}))({}, {})", "({}, {'k': {'b': 2}})"),
           ("dict.fromkeys('abc', 0)", "{'a': 0, 'b': 0, 'c': 0}"), ("dict.fromkeys('ab')", "{'a': None, 'b': None}"),
           ("(lambda d: d['a'] is d['b'])(dict.fromkeys('ab', []))", "True"),
           ("(lambda d: (d['a'].append(1), d)[1])(dict.fromkeys('ab', []))", "{'a': [1], 'b': [1]}"),
           ("{k: [] for k in 'ab'}", "{'a': [], 'b': []}"), ("(lambda d: d['a'] is d['b'])({k: [] for k in 'ab'})", "False"),
           ("list(dict.fromkeys(['b', 'a', 'b', 'c', 'a']))", "['b', 'a', 'c']"),
           ("(lambda d: (d.__setitem__('Eve', 'Dec 5'), d.__setitem__('Bob', 'Dec 13'), list(d), len(d))[2:])({'Alice': 'Apr 1', 'Bob': 'Dec 12'})", "(['Alice', 'Bob', 'Eve'], 3)"),
           ("(lambda d: (d.setdefault('k', []).append(1), d.setdefault('k', []).append(2), d)[2])({})", "{'k': [1, 2]}"),
